    open
    heading="Invoice 4821"
    actions={[
      { id: 'download', label: 'Download' },
      { id: 'void', label: 'Void invoice', tone: 'danger', disabled: true },
    ]}
    cancelLabel="Not now" />;

const Closed = () => <ActionSheetConsumer
    open={false}
    heading="Photo.jpg"
    actions={[
      { id: 'share', label: 'Share', icon: 'external' },
      { id: 'rename', label: 'Rename' },
      { id: 'duplicate', label: 'Duplicate' },
      { id: 'delete', label: 'Delete photo', icon: 'danger', tone: 'danger' },
    ]} />;

const NotDismissible = () => <ActionSheetConsumer
    open
    heading="Photo.jpg"
    actions={[
      { id: 'share', label: 'Share', icon: 'external' },
      { id: 'rename', label: 'Rename' },
      { id: 'duplicate', label: 'Duplicate' },
      { id: 'delete', label: 'Delete photo', icon: 'danger', tone: 'danger' },
    ]}
    dismissible={false} />;

const WithOverrides = () => <ActionSheetConsumer
    open
    heading="Photo.jpg"
    actions={[
      { id: 'share', label: 'Share', icon: 'external' },
      { id: 'rename', label: 'Rename' },
      { id: 'duplicate', label: 'Duplicate' },
      { id: 'delete', label: 'Delete photo', icon: 'danger', tone: 'danger' },
    ]}
    overrides={{ radius: 'radius.md', itemPaddingBlock: 'space.md', headerGap: 'layout.gap.normal' }} />;

const PresentAtLoad = () => <Alert
    tone="warning"
    live="off"
    dismissible={false}
    heading="Trial ends in three days">Add a payment method to keep your workspace.</Alert>;

const Keyboard = (args) => {
  function Open(): React.JSX.Element {
    const [open, setOpen] = React.useState(true);
    return (
      <Stack gap="loose" align="start">
        <Button label="Delete files" variant="danger" onPress={() => setOpen(true)} />
        <AlertDialog
          {...args}
          open={open}
          onCancel={() => setOpen(false)}
          onConfirm={() => setOpen(false)}
        />
      </Stack>
    );
  }
  return <Open />;
};

const NotDismissible = () => <BottomSheet
    open
    heading="Filters"
    footer={(<>
      <Button label="Delete account" variant="danger" />
      <Button label="Keep account" variant="secondary" />
    </>)}
    height="content"
    dismissible={false}
    dragToDismiss><Text>Narrow results by price, distance and rating.</Text></BottomSheet>;

const HalfHeightResults = () => <BottomSheet
    open
    heading="Nearby places"
    footer={(<>
      <Button label="Apply" variant="primary" />
      <Button label="Reset" variant="secondary" />
    </>)}
    height="half"
    dismissible
    dragToDismiss>(<Stack gap="normal">
      {['Corner Café', 'City Library', 'Riverside Park', 'Market Hall', 'Bike Repair', 'Post Office', 'Bakery'].map(
        (place) => (
          <Link key={place} href="#" label={place} />
        ),
      )}
    </Stack>)</BottomSheet>;

const Keyboard = (args) => {
  function Open(): React.JSX.Element {
    const [open, setOpen] = React.useState(true);
    return (
      <Stack gap="loose" align="start">
        <Button label="Open filters" onPress={() => setOpen(true)} />
        <BottomSheet
          {...args}
          open={open}
          onClose={() => setOpen(false)}
          footer={
            <>
              <Button label="Apply" variant="primary" onPress={() => setOpen(false)} />
              <Button label="Reset" variant="secondary" onPress={() => setOpen(false)} />
            </>
          }
        >
          <Stack gap="loose">
            <Input label="Minimum price" name="min-price" />
            <Input label="Maximum price" name="max-price" />
            <Link href="#" label="Clear all filters" />
          </Stack>
        </BottomSheet>
      </Stack>
    );
  }
  return <Open />;
};

