    const [open, setOpen] = React.useState(true);
    const triggerRef = React.useRef<ViewInstance>(null);
    return (
      <Stack gap="loose" align="start">
        <View ref={triggerRef} collapsable={false}>
          <Button label="Open panel" onPress={() => setOpen(true)} />
